const body = $input.first().json;
const opps = (body.data && (body.data.opportunities || Object.values(body.data)[0])) || [];
const shortlist = opps.filter(o => o.stage === 'SHORTLIST');
if (!shortlist.length) return [{ json: { empty: true, doc: 'No deals in Shortlist this week.' } }];
const items = shortlist.map(o => {
  const comp = o.company || {};
  const p = o.pointOfContact || {};
  const pName = p.name && typeof p.name === 'object' ? ((p.name.firstName || '') + ' ' + (p.name.lastName || '')).trim() : (p.name || '');
  return {
    company: comp.name || (o.name || '').split(' (')[0],
    domain: (comp.domainName && comp.domainName.primaryLinkUrl) || '',
    deal: o.name,
    board_score: o.score,
    tags: o.tags || '',
    one_liner: o.oneLiner || '',
    founder: pName + (p.jobTitle ? ' (' + p.jobTitle + ')' : ''),
    notes: o.notes || '(no notes in CRM)',
  };
});
return [{ json: { empty: false, items } }];

const prev = $('Build Claude request').first().json;
if (prev.skip) return [{ json: { doc: prev.doc } }];
const resp = $input.first().json;
if (resp.error) return [{ json: { doc: 'Shortlist error: ' + ((resp.error.message || '').slice(0, 200)) } }];
const texts = (resp.content || []).filter(b => b.type === 'text').map(b => b.text);
const doc = (texts[texts.length - 1] || '').trim() || 'Shortlist error: empty model output';
return [{ json: { doc } }];
